dtsPropsFor.Icon:
/** Which icon (the app's full set). */
  name: "today" | "schedule" | "paw" | "owners" | "stethoscope" | "pill" | "receipt" | "chart" | "settings" | "search" | "plus" | "back" | "chevron-left" | "chevron-right" | "refresh" | "alert" | "shield" | "home" | "bell" | "close" | "check" | "trash" | "print" | "mail" | "download" | "lock" | "clock" | "info" | "warning" | "minus" | "card" | "cash" | "bank" | "syringe" | "truck" | "clipboard" | "label" | "sign-out" | "file" | "weight" | "edit";
  /** Width and height in pixels. Defaults to 20. */
  size?: number;

dtsPropsFor.PatientSearch:
/** The practice's patients to search (name, owner, phone, microchip). The top five matches show, in this order. */
  patients: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] }[];
  /** Picking a match (click, or Enter). */
  onOpen?: (patient: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] }) => void;
  /** "Search all patients", or Enter with no single match. */
  onSearchAll?: (text: string) => void;
  /** Text already in the box, with its dropdown open (for a static mockup of the search in use). */
  defaultQuery?: string;

dtsPropsFor.PatientPicker:
/** The chosen patient: shows as a card with a Change button instead of the search. */
  selected?: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] } | null;
  /** Picking a patient, or null for Change. */
  onSelectedChange?: (patient: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] } | null) => void;
  /** The patient can't be changed. */
  locked?: boolean;
  /** Defaults to "picker-search". */
  inputId?: string;
  /** The practice's patients to search (up to six matches show). */
  patients?: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] }[];
  /** Shown before anything is typed: the four patients seen most recently. */
  recent?: { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] }[];
  /** "Add and select" in the new client form. Return the new patient to select it. */
  onAddNew?: (draft: { ownerName: string; phone: string; petName: string; species: string }) => { id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] } | void | Promise<{ id: number; name: string; patientNumber?: string; species: string; speciesAndBreed: string; ownerName: string; ownerPhone?: string; microchip?: string | null; allergyLabels?: string[] } | void>;
  /** Text already in the box (static mockup). */
  defaultQuery?: string;
  /** Start with the "New client and patient" form open. */
  defaultNewOpen?: boolean;

dtsPropsFor.ProductSearch:
/** The price list to search by name or code (up to twelve matches show, in this order). allergyConflicts are the current patient's allergies the product conflicts with. */
  products: { id: number; code: string; name: string; category: "Service" | "Medicine" | "Vaccine" | "Retail"; grossPrice: number; unit: string; isControlledDrug?: boolean; isStocked?: boolean; onHand?: number; allergyConflicts?: string[] }[];
  /** Only these categories, e.g. ["Medicine"] when prescribing. */
  categories?: ("Service" | "Medicine" | "Vaccine" | "Retail")[];
  /** Only products kept in stock. */
  stockedOnly?: boolean;
  /** Defaults to "Search the price list". */
  placeholder?: string;
  /** Defaults to "product-search". */
  inputId?: string;
  /** Picking a product;
  the box then clears. */ onPick?: (product: { id: number; code: string; name: string; category: "Service" | "Medicine" | "Vaccine" | "Retail"; grossPrice: number; unit: string; isControlledDrug?: boolean; isStocked?: boolean; onHand?: number; allergyConflicts?: string[] }) => void;
  /** Text already in the box, with its dropdown open (static mockup). */
  defaultQuery?: string;

dtsPropsFor.ChargeForm:
/** The product picked from the price list. grossPrice is per unit including VAT, in pounds. */
  product: { name: string; grossPrice: number; unit: string; isControlledDrug?: boolean; isStocked?: boolean; onHand?: number };
  /** A prescription: asks for label directions and the button reads "Prescribe". */
  isPrescription?: boolean;
  /** Allergies the product conflicts with, e.g. ["Penicillin"]. Any conflict needs a written reason to go ahead. */
  conflicts?: string[];
  /** The signed-in person may prescribe (a vet), so may override an allergy warning. Defaults to true. */
  canOverride?: boolean;
  onCancel?: () => void;
  onAdd?: (charge: { product: { name: string; grossPrice: number; unit: string; isControlledDrug?: boolean; isStocked?: boolean; onHand?: number }; quantity: number; isPrescription: boolean; directions: string | null; overrideReason: string | null }) => void;

dtsPropsFor.AlertEditor:
/** The alert being edited. Leave out id for a new alert;
  presetKey null starts at the pick-list, "custom" for typed-in text. */ alert: { id?: number | null; presetKey?: string | null; text: string; severity: "Alert" | "Warning" | "Note" };
  onClose?: () => void;
  onSave?: (alert: { id?: number | null; presetKey?: string | null; text: string; severity: "Alert" | "Warning" | "Note" }) => void;
  /** After the user confirms in the delete dialog. */
  onDelete?: (id: number) => void;

dtsPropsFor.WitnessPicker:
/** Prefix for the two input ids. Defaults to "witness". */
  id?: string;
  /** Staff who may witness (not whoever is signed in). shortName is the first name. */
  witnesses: { id: number; shortName: string; jobTitle: string }[];
  witnessId?: number | null;
  onWitnessIdChange?: (id: number | null) => void;
  pin?: string | null;
  onPinChange?: (pin: string) => void;

dtsPropsFor.Toasts:
/** The toasts showing now, oldest first (the app keeps at most four). kind defaults to Success. */
  toasts: { id: string; text: string; kind?: "Success" | "Warning" | "Error" }[];
  /** The close button on a toast. */
  onDismiss?: (id: string) => void;
